var field = new OtpField(6, slotSize: 46, gap: 8, label: "Verification code")
{
    Value = DemoCode
};

field.Completed += (_, value) => Verify(value);

var card = AppKit.Card(new StackPanel
{
    Spacing = 14,
    Children =
    {
        AppKit.Row(9, AppKit.Disc("shield-check", 34, 16, true),
            new TextBlock { Text = "Verify your email", Classes = { "arc-body", "arc-medium" } }),
        AppKit.Caption("We sent a code to maya@northwind.co"),
        AppKit.Field("Verification code", field),
        feedback,
        AppKit.Btn("Verify code", ArcButtonVariant.Primary, ArcButtonSize.Md, Verify, height: 42, stretch: true),
        AppKit.Link("Use a different email", () => { }, icon: "arrow-left")
    }
}, 18, 18);

return AppKit.Screen(new Border { Padding = new Thickness(24), Child = card }, 400);
